<?php
namespace App\Http\Controllers;
use App\Services\DocumentWorkflowService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class DocumentWorkflowController extends Controller{
public function __construct(private DocumentWorkflowService $wf){}
private function view(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->canDo('edo.view')||$r->user()->canDo('edo.manage')||$r->user()->canDo('edo.approve'),403);}
private function manage(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->canDo('edo.manage'),403);}
public function index(Request $r){$this->view($r);$q=DB::table('official_documents as d')->leftJoin('users as u','u.id','=','d.created_by')->select('d.*','u.name author_name')->orderByDesc('d.id');if($r->filled('direction'))$q->where('d.direction',$r->direction);if($r->filled('status'))$q->where('d.status',$r->status);if($r->filled('q'))$q->where(function($x)use($r){$x->where('d.number','like','%'.$r->q.'%')->orWhere('d.title','like','%'.$r->q.'%')->orWhere('d.correspondent','like','%'.$r->q.'%');});return view('edo.index',['items'=>$q->limit(300)->get()]);}
public function create(Request $r){$this->manage($r);$users=DB::table('users')->where('is_active',1)->orderBy('name')->get();return view('edo.create',compact('users'));}
public function store(Request $r){$this->manage($r);$d=$r->validate(['direction'=>'required|in:incoming,outgoing,internal','type'=>'required|string|max:100','title'=>'required|string|max:500','document_date'=>'nullable|date','external_number'=>'nullable|string|max:100','correspondent'=>'nullable|string|max:500','confidentiality'=>'required|in:public,internal,restricted','due_on'=>'nullable|date','summary'=>'nullable|string|max:10000','body'=>'nullable|string|max:50000']);$p=$r->attributes->get('academic_period');$id=DB::transaction(function()use($r,$d,$p){$seq=(DB::table('official_documents')->max('id')??0)+1;$num=sprintf('DOC-%s-%06d',date('Y'),$seq);$id=DB::table('official_documents')->insertGetId(['number'=>$num,'type'=>$d['type'],'academic_period_id'=>$p->id,'direction'=>$d['direction'],'title'=>$d['title'],'document_date'=>$d['document_date']??date('Y-m-d'),'external_number'=>$d['external_number']??null,'correspondent'=>$d['correspondent']??null,'confidentiality'=>$d['confidentiality'],'due_on'=>$d['due_on']??null,'summary'=>$d['summary']??null,'status'=>'draft','current_version'=>1,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);DB::table('document_versions')->insert(['official_document_id'=>$id,'version'=>1,'title'=>$d['title'],'body'=>$d['body']??null,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);$this->wf->event($id,$r->user()->id,'created','Создан документ ЭДО');return $id;});return redirect()->route('edo.show',$id);}
public function show(Request $r,$id){$this->view($r);$d=DB::table('official_documents')->find($id);abort_if(!$d,404);$v=DB::table('document_versions')->where(['official_document_id'=>$id,'version'=>$d->current_version])->first();$routes=DB::table('document_routes as x')->leftJoin('users as u','u.id','=','x.assignee_user_id')->leftJoin('users as a','a.id','=','x.acted_by')->where('x.official_document_id',$id)->select('x.*','u.name assignee_name','a.name acted_name')->orderBy('x.step')->get();$files=DB::table('document_attachments')->where('official_document_id',$id)->get();$tasks=DB::table('document_tasks as t')->join('users as u','u.id','=','t.assigned_to')->where('t.official_document_id',$id)->select('t.*','u.name assignee_name')->get();$acks=DB::table('document_acknowledgements as a')->join('users as u','u.id','=','a.user_id')->where('a.official_document_id',$id)->select('a.*','u.name')->get();$events=DB::table('official_document_events as e')->leftJoin('users as u','u.id','=','e.user_id')->where('e.official_document_id',$id)->select('e.*','u.name user_name')->orderByDesc('e.id')->limit(100)->get();$users=DB::table('users')->where('is_active',1)->orderBy('name')->get();return view('edo.show',compact('d','v','routes','files','tasks','acks','events','users'));}
public function register(Request $r,$id){$this->manage($r);$d=DB::table('official_documents')->find($id);abort_if(!$d||$d->status!=='draft',409);DB::table('official_documents')->where('id',$id)->update(['status'=>'registered','registered_at'=>now(),'registered_by'=>$r->user()->id,'updated_at'=>now()]);$this->wf->event($id,$r->user()->id,'registered','Документ зарегистрирован');return back();}
public function version(Request $r,$id){$this->manage($r);$d=DB::table('official_documents')->find($id);abort_if(!$d||in_array($d->status,['signed','closed','archived']),409);$x=$r->validate(['title'=>'required|string|max:500','body'=>'nullable|string|max:50000']);$n=$d->current_version+1;DB::transaction(function()use($id,$n,$x,$r){DB::table('document_versions')->insert(['official_document_id'=>$id,'version'=>$n,'title'=>$x['title'],'body'=>$x['body']??null,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);DB::table('official_documents')->where('id',$id)->update(['title'=>$x['title'],'current_version'=>$n,'updated_at'=>now()]);});$this->wf->event($id,$r->user()->id,'versioned','Создана версия '.$n);return back();}
public function file(Request $r,$id){$this->manage($r);$d=DB::table('official_documents')->find($id);abort_if(!$d||in_array($d->status,['signed','closed','archived']),409);$r->validate(['file'=>'required|file|max:20480']);$f=$r->file('file');$path=$f->store('edo/'.$id,'local');DB::table('document_attachments')->insert(['official_document_id'=>$id,'version'=>$d->current_version,'original_name'=>$f->getClientOriginalName(),'path'=>$path,'mime'=>$f->getMimeType(),'size'=>$f->getSize(),'sha256'=>hash_file('sha256',$f->getRealPath()),'uploaded_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);$this->wf->event($id,$r->user()->id,'file_added',$f->getClientOriginalName());return back();}
}